//! Locating and launching an `ark` kernel when the console isn't attaching to
//! an existing one.

use std::net::TcpListener;
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::time::{Duration, Instant};

use anyhow::{bail, Context, Result};

use crate::jupyter::ConnectionInfo;

pub struct SpawnedKernel {
    pub child: Child,
    connection_file: PathBuf,
    pub log_file: PathBuf,
    dir: PathBuf,
    /// The log path was generated by us rather than passed with `--log`.
    auto_log: bool,
    /// Set once the session ends normally; auto-generated logs are then deleted.
    pub clean_exit: bool,
}

impl SpawnedKernel {
    pub fn has_exited(&mut self) -> bool {
        !matches!(self.child.try_wait(), Ok(None))
    }

    pub fn exited_successfully(&mut self) -> bool {
        matches!(self.child.try_wait(), Ok(Some(status)) if status.success())
    }

    /// Waits briefly for a requested shutdown, then kills the process.
    pub fn stop(&mut self, grace: Duration) {
        let deadline = Instant::now() + grace;
        while Instant::now() < deadline {
            if self.has_exited() {
                return;
            }
            std::thread::sleep(Duration::from_millis(50));
        }
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

impl Drop for SpawnedKernel {
    fn drop(&mut self) {
        if !self.has_exited() {
            let _ = self.child.kill();
            let _ = self.child.wait();
        }
        let _ = std::fs::remove_file(&self.connection_file);
        if self.auto_log && self.clean_exit {
            let _ = std::fs::remove_file(&self.log_file);
        }
        // Only removed if empty, i.e. a kept log survives for debugging.
        let _ = std::fs::remove_dir(&self.dir);
    }
}

/// Resolves the ark binary: explicit flag, `$ARK_PATH`, `ark` on `PATH`, then
/// the in-repo development build.
pub fn find_ark(explicit: Option<PathBuf>) -> Result<PathBuf> {
    if let Some(p) = explicit.or_else(|| std::env::var_os("ARK_PATH").map(PathBuf::from)) {
        if p.is_file() {
            return Ok(p);
        }
        bail!("ark binary not found at {}", p.display());
    }
    if let Some(path) = std::env::var_os("PATH") {
        for dir in std::env::split_paths(&path) {
            let candidate = dir.join("ark");
            if candidate.is_file() {
                return Ok(candidate);
            }
        }
    }
    let vendor = Path::new(env!("CARGO_MANIFEST_DIR")).join("../vendor/ark/target");
    for profile in ["release", "debug"] {
        let candidate = vendor.join(profile).join("ark");
        if candidate.is_file() {
            return Ok(candidate);
        }
    }
    bail!("could not find `ark`; pass --ark <path> or set ARK_PATH")
}

fn free_port() -> Result<u16> {
    Ok(TcpListener::bind("127.0.0.1:0")?.local_addr()?.port())
}

pub fn spawn(ark: &Path, log_file: Option<PathBuf>) -> Result<(SpawnedKernel, ConnectionInfo)> {
    let dir = std::env::temp_dir().join(format!("betterr-{}", std::process::id()));
    std::fs::create_dir_all(&dir)?;

    let info = ConnectionInfo {
        shell_port: free_port()?,
        iopub_port: free_port()?,
        stdin_port: free_port()?,
        control_port: free_port()?,
        hb_port: free_port()?,
        ip: "127.0.0.1".into(),
        key: uuid::Uuid::new_v4().simple().to_string(),
        transport: "tcp".into(),
        signature_scheme: "hmac-sha256".into(),
        kernel_name: Some("ark".into()),
    };
    let connection_file = dir.join("kernel.json");
    write_private(&connection_file, &serde_json::to_vec_pretty(&info)?)?;
    let auto_log = log_file.is_none();
    let log_file = log_file.unwrap_or_else(|| dir.join("ark.log"));

    let child = Command::new(ark)
        .arg("--connection_file")
        .arg(&connection_file)
        .args(["--session-mode", "console", "--log"])
        .arg(&log_file)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .with_context(|| format!("launching {}", ark.display()))?;

    Ok((
        SpawnedKernel {
            child,
            connection_file,
            log_file,
            dir,
            auto_log,
            clean_exit: false,
        },
        info,
    ))
}

/// The connection file holds the HMAC key, so keep it owner-readable only.
fn write_private(path: &Path, bytes: &[u8]) -> Result<()> {
    use std::io::Write;
    use std::os::unix::fs::OpenOptionsExt;
    let mut f = std::fs::OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .mode(0o600)
        .open(path)?;
    f.write_all(bytes)?;
    Ok(())
}
